import type { BlogArticleFaq } from '../../../types/blog';

export const BODY: string = "\n<p>معظم الضواغط تقدم أحجامًا ثابتة: 50 أو 100 أو 200 أو 500 كيلوبايت. لكن ماذا إذا طلبت بوابتك 80 كيلوبايت بالضبط؟</p>\n<p>هنا يعمل <a href=\"/ar/daght-as-sura-ila-hajm-muayyan/\">ضاغط حجم الملف المستهدف</a>. تكتب أي حجم تحتاجه، وتصل الأداة إليه بدقة.</p>\n<p>يشرح هذا الدليل كيف تعمل الأهداف المخصصة، ومتى تستخدمها، وكيف تحصل على أفضل نتيجة منها.</p>\n<h2 id=\"what-is-target-compression\">ما هو الضغط إلى حجم ملف مستهدف؟</h2>\n<p>الضغط إلى حجم ملف مستهدف يعني كتابة الرقم الذي تريده بالضبط، مثل 80 أو 150 أو 350 كيلوبايت، وترك الأداة تصل إليه.</p>\n<p>بدل الاختيار من قائمة ثابتة، تحدد هدفك بنفسك. هذه المرونة تحل مشكلة البوابات ذات الحدود غير المعتادة.</p>\n<h2 id=\"how-it-works\">كيف تعمل الأداة؟</h2>\n<p>تعمل الأداة بالبحث الثنائي عن الجودة. تختبر مستويات جودة مختلفة حتى تجد الأعلى الذي ما زال يناسب هدفك بالضبط.</p>\n<p>إذا لم تكفِ الجودة وحدها، تقلّص الأداة الأبعاد تدريجيًا. التقليص البطيء يحافظ على أكبر قدر ممكن من التفاصيل.</p>\n<h2 id=\"kb-vs-mb\">كيلوبايت مقابل ميغابايت: كيف تختار الوحدة الصحيحة؟</h2>\n<p>اختر الكيلوبايت للأهداف الصغيرة مثل 80 أو 150، والميغابايت للأهداف الكبيرة مثل 1 أو 2 ميغابايت. الوحدة الصحيحة تمنع أخطاء الإدخال.</p>\n<p>انتبه إلى الفرق بين الوحدتين: 1 ميغابايت يساوي 1024 كيلوبايت تقريبًا. كتابة 1 في خانة الكيلوبايت تعطي هدفًا مختلفًا تمامًا.</p>\n<h2 id=\"when-to-use-custom\">متى تستخدم هدفًا مخصصًا؟</h2>\n<p>استخدم هدفًا مخصصًا عندما يكون حد البوابة غير معتاد: 80 أو 120 أو 150 أو 350 كيلوبايت. هذه الأرقام لا توجد في الأدوات الثابتة.</p>\n<p>كما تستخدمه عندما تريد حجمًا محددًا لسبب تقني، مثل حد مرفقات البريد أو سعة تخزين معينة. الهدف المخصص يعطيك تحكمًا كاملًا.</p>\n<h2 id=\"binary-search-explained\">البحث الثنائي عن الجودة بكلمات بسيطة</h2>\n<p>البحث الثنائي عن الجودة ببساطة: الأداة تختبر جودة في المنتصف، فإذا كان الملف أكبر من الهدف تخفض الجودة، وإذا كان أصغر ترفعها.</p>\n<p>كل اختبار يقلّص النطاق إلى النصف، فتصل الأداة إلى أفضل جودة ممكنة في خطوات قليلة. النتيجة هي أوضح نسخة تناسب هدفك.</p>\n<h2 id=\"dimension-scaling\">التقليص الذكي للأبعاد</h2>\n<p>التقليص الذكي للأبعاد يعني خفض الأبعاد فقط عندما لا تكفي الجودة. الأداة تحاول الجودة أولًا بالحجم الكامل، ثم تقلّص خطوة بخطوة.</p>\n<p>يمكنك أيضًا قص الصورة قبل الضغط. إزالة المساحات الفارغة تمنح الموضوع الرئيسي حصة أكبر من ميزانية الهدف.</p>\n<h2 id=\"impossible-targets\">عندما يكون الهدف مستحيلًا</h2>\n<p>بعض الأهداف مستحيلة فعلًا. صورة جماعية مزدحمة بهدف 20 كيلوبايت، أو صورة مفصلة بصيغة PNG بهدف صغير جدًا، قد لا تصل أبدًا.</p>\n<p>عندما يظهر تحذير الهدف غير المحقق، فغيّر الصيغة إلى JPG أو قصّ الصورة بإحكام أو ارفع الهدف قليلًا. الهدف المستحيل مشكلة إعدادات لا مشكلة صورة.</p>\n<h2 id=\"formats-custom\">الصيغ للأهداف المخصصة</h2>\n<p>للأهداف المخصصة، JPG هو الخيار الآمن للصور الفوتوغرافية. يعطي أصغر ملف بأفضل جودة، وتقبله كل البوابات.</p>\n<p>WebP أصغر قليلًا لكن بعض البوابات ترفضه. أما PNG فيناسب النصوص والرسوم فقط، ونادرًا ما يصل إلى الأهداف الصغيرة مع الصور.</p>\n<h2 id=\"batch-custom\">الضغط بالجملة إلى هدف مخصص</h2>\n<p>الضغط بالجملة إلى هدف مخصص يعمل مثل الضغط الفردي: كل صورة في الدفعة تُضغط إلى الحجم نفسه الذي حددته.</p>\n<p>هذه الطريقة مثالية عندما تطلب منصة ما حجمًا موحدًا لكل الصور. ارفع الدفعة وحدد الهدف مرة واحدة، ثم نزّل كل شيء كملف ZIP.</p>\n<h2 id=\"common-mistakes\">أخطاء شائعة مع الأهداف المخصصة</h2>\n<p>أكثر الأخطاء شيوعًا كتابة الوحدة الخاطئة: 80 ميغابايت بدل 80 كيلوبايت. تحقق من الوحدة قبل الضغط، فالفرق هائل.</p>\n<p>خطأ آخر أن تبدأ من نسخة مضغوطة أصلًا. كل جولة ضغط تضيف ضررًا، فابدأ دائمًا من الملف الأصلي بأعلى جودة.</p>\n<h2 id=\"privacy-custom\">الخصوصية مع الأهداف المخصصة</h2>\n<p>الخصوصية مع الأهداف المخصصة مثل أي ضغط: كل المعالجة تتم على جهازك، ولا تُرفع صورتك إلى أي خادم.</p>\n<p>هذا مهم خصوصًا مع صور الهوية والمستندات. يمكنك ضغطها إلى أي هدف دون قلق بشأن تسرب البيانات.</p>\n<h2 id=\"unit-mistakes\">أخطاء الوحدة وكيف تتجنبها</h2>\n<p>أخطاء الوحدة شائعة: كتابة 1 ميغابايت في خانة الكيلوبايت، أو الخلط بين KB وMB. تحقق دائمًا من الوحدة المعروضة بجانب الرقم.</p>\n<p>إذا بدا الهدف مستحيلًا، فتحقق من الوحدة أولًا. كثير من الأهداف المستحيلة سببها خطأ وحدة بسيط.</p>\n<h2 id=\"target-for-email\">أهداف مخصصة لمرفقات البريد</h2>\n<p>للأهداف المخصصة لمرفقات البريد، اختر حجمًا يترك مساحة لبقية الرسالة. إذا كان حد الرسالة 25 ميغابايت، فاجعل الصور مجتمعة أقل من 20 ميغابايت.</p>\n<p>لصورة واحدة في رسالة، 200 إلى 500 كيلوبايت مناسب. الصورة الخفيفة تحمل بسرعة ولا تتجاوز حدود البريد.</p>\n<h2 id=\"target-for-print-prep\">كيف تجهّز الصور للطباعة بأهداف مخصصة؟</h2>\n<p>للتحضير للطباعة بأهداف مخصصة، تذكر أن الطباعة تحتاج الملف الأصلي. الهدف المخصص مفيد لتقليل حجم ملف الطباعة للنقل، لا لاستبدال الأصل.</p>\n<p>اضغط نسخة للنقل بهدف مناسب، واحتفظ بالأصل للطباعة الفعلية. النسخة المضغوطة للنقل، والأصل للورق.</p>\n<h2 id=\"comparing-targets\">كيف تقارن عدة أهداف في صورة واحدة؟</h2>\n<p>لمقارنة عدة أهداف في صورة واحدة، اضغط نسخًا بأهداف مختلفة وقارنها جنبًا إلى جنب. لاحظ متى يبدأ فقدان الجودة في الظهور.</p>\n<p>هذه المقارنة تعلّمك الحد الأدنى المقبول لصورك. بعدها تختار الهدف الأصغر الذي ما زال يبدو جيدًا.</p>\n<h2 id=\"saving-presets\">كيف تحفظ أهدافك الشائعة؟</h2>\n<p>احفظ أهدافك الشائعة في قائمة: 80 كيلوبايت لبوابة معينة، و150 لمدونتك، و350 لمعرضك. القائمة تختصر كتابة الرقم في كل مرة.</p>\n<p>سمِّ كل هدف بغرضه، لا برقمه فقط. اسم مثل هدف-بوابة-التوظيف أوضح من رقم مجرد.</p>\n<h2 id=\"accessibility-custom\">إمكانية الوصول مع الأهداف المخصصة</h2>\n<p>إمكانية الوصول مع الأهداف المخصصة تعني الحفاظ على وضوح النص والتباين الجيد. الهدف الصغير جدًا قد يجعل النص غير مقروء.</p>\n<p>إذا كان النص مهمًا في صورتك، فاختر هدفًا أكبر أو حافظ على الأبعاد كبيرة. وضوح النص أهم من تصغير الحجم. وللخطوات العملية، اقرأ <a href=\"/ar/blog/kayfiyya-daght-as-sura-ila-kb-muhaddad/\">كيفية ضغط صورة إلى حجم دقيق بالكيلوبايت</a> و<a href=\"/ar/blog/al-bahth-al-thunai-an-al-jawda-li-hadaf-kb-daqiq/\">الأهداف الدقيقة بالكيلوبايت: البحث الثنائي عن الجودة</a>، أو جرّب <a href=\"/ar/daght-as-sura-ila-100kb/\">ضاغط 100 كيلوبايت</a> و<a href=\"/ar/daght-as-sura-ila-200kb/\">ضاغط 200 كيلوبايت</a> للأحجام الشائعة.</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"ما نطاق الأحجام التي يمكنني كتابتها في ضاغط الهدف؟","answer":"يمكنك كتابة أي حجم من بضعة كيلوبايتات إلى عدة ميغابايتات. الأداة تدعم الكيلوبايت والميغابايت، لكن الأهداف الصغيرة جدًا قد تكون مستحيلة للصور المفصلة."},{"question":"ما مدى دقة حجم الملف النهائي مقارنة بهدفي؟","answer":"دقيق جدًا. الأداة تستهدف أقل بقليل من الهدف، عادة بفارق بضعة كيلوبايتات. إذا طلبت 80 كيلوبايت، فستحصل على 78 أو 79 كيلوبايت غالبًا."},{"question":"هل يمكنني ضغط دفعة صور إلى الحجم المخصص نفسه؟","answer":"نعم، يمكنك معالجة دفعة كاملة بالهدف نفسه. كل صورة في الدفعة تُضغط إلى الحجم المخصص الذي حددته، وتنزّل النتائج كملف ZIP."},{"question":"ماذا يحدث إذا رفعت صورة أصغر من هدفي أصلًا؟","answer":"لا مشكلة. الأداة تترك الصورة الأصغر من الهدف كما هي دون تغيير. لا فائدة من تكبير ملف صغير ليصل إلى هدف أكبر."},{"question":"لماذا تختبر الأداة الجودة قبل تقليص الأبعاد؟","answer":"لأن خفض الجودة يحافظ على الأبعاد والتفاصيل، بينما تقليص الأبعاد يقلل التفاصيل المتاحة من الأساس. الجودة أولًا تعطي أفضل نتيجة بأي حجم."},{"question":"هل من الأفضل استخدام أداة ثابتة أم أداة الهدف المخصص؟","answer":"إذا كان هدفك حجمًا شائعًا مثل 50 أو 100 أو 200 كيلوبايت، فالأداة الثابتة أسرع. أما إذا كان هدفك غير معتاد مثل 80 أو 150 كيلوبايت، فأداة الهدف المخصص هي الخيار الصحيح."}];
